(3866545, 544880, 62626, '<td valign="top">Nice pic of the mountains. The bush in the foreground is a little distracting.</td>', 'Nice pic of the mountains. The bush in the foreground is a little distracting.', '2007-07-04 09:19:52.000000', NULL, 1),
(3866548, 546515, 49109, '<td valign="top">would crop off the ground and correct the tilt. sky needs some more "drama"</td>', 'would crop off the ground and correct the tilt. sky needs some more "drama"', '2007-07-04 09:20:14.000000', NULL, 1),
(3866550, 547143, 62626, '<td valign="top">great angle and title!</td>', 'great angle and title!', '2007-07-04 09:20:32.000000', NULL, 1),
