(3888472, 548026, 72058, '<td valign="top">Good use of DOF</td>', 'Good use of DOF', '2007-07-10 09:28:55.000000', NULL, 1),
(3888480, 547143, 72058, '<td valign="top">I like it!  Fantastic find and great title.</td>', 'I like it!  Fantastic find and great title.', '2007-07-10 09:30:02.000000', NULL, 1),
(3888481, 547571, 72058, '<td valign="top">A Truly wonderful image!</td>', 'A Truly wonderful image!', '2007-07-10 09:30:27.000000', NULL, 1),
(3888482, 547602, 72058, '<td valign="top">Beautiful colours and the border works well too.</td>', 'Beautiful colours and the border works well too.', '2007-07-10 09:30:51.000000', NULL, 1),
(3888484, 547375, 72058, '<td valign="top">Clear, crisp, sharp.  Excellent.</td>', 'Clear, crisp, sharp.  Excellent.', '2007-07-10 09:31:11.000000', NULL, 1),
(3888492, 548033, 72058, '<td valign="top">Beautiful!</td>', 'Beautiful!', '2007-07-10 09:34:02.000000', NULL, 1),
