(3888498, 547905, 72058, '<td valign="top">Wow, stunning location and excellent capture.</td>', 'Wow, stunning location and excellent capture.', '2007-07-10 09:36:48.000000', NULL, 1),
(3888501, 547968, 72058, '<td valign="top">Brilliant and clever!  Fantastic, crisp image and perfectly framed!</td>', 'Brilliant and clever!  Fantastic, crisp image and perfectly framed!', '2007-07-10 09:37:41.000000', NULL, 1),
(3888503, 547576, 72058, '<td valign="top">Lovely image and great title!</td>', 'Lovely image and great title!', '2007-07-10 09:38:06.000000', NULL, 1),
(3888505, 547578, 72058, '<td valign="top">Good find!</td>', 'Good find!', '2007-07-10 09:38:26.000000', NULL, 1),
