(3888528, 547060, 72058, '<td valign="top">Beautifully sharp and crisp!</td>', 'Beautifully sharp and crisp!', '2007-07-10 09:51:02.000000', NULL, 1),
(3888531, 547366, 72058, '<td valign="top">Stunning colours and composition.</td>', 'Stunning colours and composition.', '2007-07-10 09:51:47.000000', NULL, 1),
(3888536, 547499, 7743, '<td valign="top">Yellow''s a hard colour to get right.  Most of the time all the detail just blends together into a mass of colour.  I think a little more sharpening and some levels adjustment could bring out the detail in the Canola.</td>', 'Yellow''s a hard colour to get right.  Most of the time all the detail just blends together into a mass of colour.  I think a little more sharpening and some levels adjustment could bring out the detail in the Canola.', '2007-07-10 09:53:47.000000', NULL, 1),
(3888540, 545734, 72058, '<td valign="top">Interesting perspective!</td>', 'Interesting perspective!', '2007-07-10 09:54:45.000000', NULL, 1),
(3888931, 547336, 79065, '<td valign="top">very soft</td>', 'very soft', '2007-07-10 11:44:01.000000', NULL, 1),
(3888946, 547863, 74747, '<td valign="top">Interesting take on the challenge.</td>', 'Interesting take on the challenge.', '2007-07-10 11:50:59.000000', NULL, 1),
