(3888985, 548104, 74747, '<td valign="top">Love the color on this one! Really brings out the textures.</td>', 'Love the color on this one! Really brings out the textures.', '2007-07-10 12:00:39.000000', NULL, 1),
(3888989, 547610, 74747, '<td valign="top">Pretty! Love the colors and the clouds!</td>', 'Pretty! Love the colors and the clouds!', '2007-07-10 12:01:36.000000', NULL, 1),
