(3888995, 547502, 74747, '<td valign="top">I love this one - the color, the trees and the grass all combine beautifully and really make the photo. Simple yet great!</td>', 'I love this one - the color, the trees and the grass all combine beautifully and really make the photo. Simple yet great!', '2007-07-10 12:03:10.000000', NULL, 1),
(3889023, 547432, 74747, '<td valign="top">Like the photograph, but I find the tilt a little distracting. Maybe if it were straight on, it wouldn''t be so? Just IMO of course.</td>', 'Like the photograph, but I find the tilt a little distracting. Maybe if it were straight on, it wouldn''t be so? Just IMO of course.', '2007-07-10 12:14:05.000000', NULL, 1),
(3889024, 547596, 74747, '<td valign="top">Pretty and serene! Like it! One of my 10s!</td>', 'Pretty and serene! Like it! One of my 10s!', '2007-07-10 12:14:58.000000', NULL, 1),
