INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3889198, 546391, 16241, '<td valign="top">very nice, bump</td>', 'very nice, bump', '2007-07-10 13:20:20.000000', NULL, 1),
(3889254, 547999, 81038, '<td valign="top">Love the title. Very clever.</td>', 'Love the title. Very clever.', '2007-07-10 13:39:23.000000', NULL, 1),
(3889293, 547913, 81038, '<td valign="top">I LOVE THIS PICTURE. Great work!</td>', 'I LOVE THIS PICTURE. Great work!', '2007-07-10 13:56:58.000000', NULL, 1),
(3889417, 547419, 7786, '<td valign="top">Pretty serious hiking you did to get this picture and its a good one too. Lots of land here and no sea in sight.</td>', 'Pretty serious hiking you did to get this picture and its a good one too. Lots of land here and no sea in sight.', '2007-07-10 14:48:37.000000', NULL, 1),
(3889425, 546272, 7786, '<td valign="top">To blurry for my taste. Some unsharp mask and Noise filtering would help a lot.</td>', 'To blurry for my taste. Some unsharp mask and Noise filtering would help a lot.', '2007-07-10 14:51:24.000000', NULL, 1),
(3889437, 545195, 7786, '<td valign="top">Must be in New Zealand or Chile.</td>', 'Must be in New Zealand or Chile.', '2007-07-10 14:54:27.000000', NULL, 1),
(3889457, 548043, 7786, '<td valign="top">Its an excellent picture to bad its to small. Try using all the 640pixels available.</td>', 'Its an excellent picture to bad its to small. Try using all the 640pixels available.', '2007-07-10 14:59:47.000000', NULL, 1),
(3889468, 548060, 7786, '<td valign="top">Very vivid colors but I think you went little to far on blue saturation.</td>', 'Very vivid colors but I think you went little to far on blue saturation.', '2007-07-10 15:04:32.000000', NULL, 1),
(3889572, 545014, 67137, '<td valign="top">Not sure if there is a reason for the redish tint but I think it would be a better picture without it.</td>', 'Not sure if there is a reason for the redish tint but I think it would be a better picture without it.', '2007-07-10 15:37:18.000000', NULL, 1),
(3889573, 547366, 34609, '<td valign="top">Cool you got the animal in the pict!</td>', 'Cool you got the animal in the pict!', '2007-07-10 15:37:24.000000', NULL, 1),
(3889576, 548095, 67137, '<td valign="top">a puzzle? lol thats a great attempt</td>', 'a puzzle? lol thats a great attempt', '2007-07-10 15:38:46.000000', NULL, 1),
(3889585, 548095, 20056, '<td valign="top">blue is ... could I say "disgusting"? 3 from me, I hope You at least took the picture: 1 if it is a puzzle already made it.</td>', 'blue is ... could I say "disgusting"? 3 from me, I hope You at least took the picture: 1 if it is a puzzle already made it.', '2007-07-10 15:41:48.000000', NULL, 1),
(3889589, 548015, 20056, '<td valign="top">is this a joke? did You see an sky like this ever? 3</td>', 'is this a joke? did You see an sky like this ever? 3', '2007-07-10 15:42:51.000000', NULL, 1),
(3889592, 547419, 20056, '<td valign="top">Thank You... 10</td>', 'Thank You... 10', '2007-07-10 15:43:27.000000', NULL, 1),
(3889596, 546770, 20056, '<td valign="top">is the sky real? In my monitor looks unnatural...</td>', 'is the sky real? In my monitor looks unnatural...', '2007-07-10 15:44:41.000000', NULL, 1),
(3889601, 548003, 20056, '<td valign="top">Simple and very nice!</td>', 'Simple and very nice!', '2007-07-10 15:45:51.000000', NULL, 1),
(3889602, 547143, 20056, '<td valign="top">and You made the sky :)</td>', 'and You made the sky :)', '2007-07-10 15:46:31.000000', NULL, 1),
(3889606, 547772, 20056, '<td valign="top">It looks like a green cow :)</td>', 'It looks like a green cow :)', '2007-07-10 15:47:06.000000', NULL, 1),
(3889612, 548043, 20056, '<td valign="top">too much light? very difficult picture to take: 6</td>', 'too much light? very difficult picture to take: 6', '2007-07-10 15:48:01.000000', NULL, 1),
(3889616, 547840, 20056, '<td valign="top">hdrs have to look natural...</td>', 'hdrs have to look natural...', '2007-07-10 15:49:07.000000', NULL, 1),
(3889620, 546272, 20056, '<td valign="top">not bad at all! I feel the wind...</td>', 'not bad at all! I feel the wind...', '2007-07-10 15:49:55.000000', NULL, 1),
(3889624, 547571, 20056, '<td valign="top">Very difficult to control those clouds... nice idea: maybe climbing to a chair would have helped</td>', 'Very difficult to control those clouds... nice idea: maybe climbing to a chair would have helped', '2007-07-10 15:52:20.000000', NULL, 1),
(3889626, 547874, 20056, '<td valign="top">try to control those blues in the sky</td>', 'try to control those blues in the sky', '2007-07-10 15:53:01.000000', NULL, 1),
(3889631, 548107, 20056, '<td valign="top">:)<br/>I feel the wind!<br/>Very original</td>', ':)I feel the wind!Very original', '2007-07-10 15:54:56.000000', NULL, 1),
(3889648, 547659, 16075, '<td valign="top">This photo is so well composed and the lighting is wonderful.  It is a very interesting subject...even though you know an anthill is a chaotic place this picture looks so serene and peaceful.  I think I would give it an even higher score if it were in a different challenge that suited the subject matter better.</td>', 'This photo is so well composed and the lighting is wonderful.  It is a very interesting subject...even though you know an anthill is a chaotic place this picture looks so serene and peaceful.  I think I would give it an even higher score if it were in a different challenge that suited the subject matter better.', '2007-07-10 16:00:48.000000', NULL, 1),
(3889679, 548107, 16075, '<td valign="top">Awesome subject...I''ve never seen anything like this.</td>', 'Awesome subject...I''ve never seen anything like this.', '2007-07-10 16:10:35.000000', NULL, 1),
(3889726, 547044, 16075, '<td valign="top">DNMC - I don''t see any land in this picture.</td>', 'DNMC - I don''t see any land in this picture.', '2007-07-10 16:27:50.000000', NULL, 1),
(3889727, 547969, 16075, '<td valign="top">Way too much water to fit well in the category.</td>', 'Way too much water to fit well in the category.', '2007-07-10 16:28:12.000000', NULL, 1),
(3889729, 546770, 16075, '<td valign="top">To me this so obviously does not meet the challenge of Land (not sea) that I couldn''t justify giving it a higher score. It is a nice picture however.</td>', 'To me this so obviously does not meet the challenge of Land (not sea) that I couldn''t justify giving it a higher score. It is a nice picture however.', '2007-07-10 16:28:39.000000', NULL, 1),
(3889736, 547233, 16075, '<td valign="top">Obviously the subject is the Space Needle...not the land.</td>', 'Obviously the subject is the Space Needle...not the land.', '2007-07-10 16:30:29.000000', NULL, 1),
(3889740, 547809, 42100, '<td valign="top">Very nice tones and contrast...and all those big bales of hay look kind of cool!</td>', 'Very nice tones and contrast...and all those big bales of hay look kind of cool!', '2007-07-10 16:31:10.000000', NULL, 1),
(3889745, 547913, 42100, '<td valign="top">Very nice light and color...nice warm temperature to this.  Great clarity as well.  Well done!</td>', 'Very nice light and color...nice warm temperature to this.  Great clarity as well.  Well done!', '2007-07-10 16:32:33.000000', NULL, 1),
(3889770, 547218, 3087, '<td valign="top">The landscape is interesting, and the double rainbow, together with the red light on the hills to the right, are both striking. But as a whole the image doesn''t work for me, perhaps because of the large swathe of brown mud in the foreground or perhaps because the fence posts make me feel like I''m separated from the landscape rather then within it.</td>', 'The landscape is interesting, and the double rainbow, together with the red light on the hills to the right, are both striking. But as a whole the image doesn''t work for me, perhaps because of the large swathe of brown mud in the foreground or perhaps because the fence posts make me feel like I''m separated from the landscape rather then within it.', '2007-07-10 16:41:34.000000', NULL, 1),
(3889771, 547976, 3087, '<td valign="top">Really like the way that the grassland itself is emphasised by your perspective here. The detail and patterns of it are just lovely. And the perfect detail in the sky as well as the band of rocks and hills is just perfect.</td>', 'Really like the way that the grassland itself is emphasised by your perspective here. The detail and patterns of it are just lovely. And the perfect detail in the sky as well as the band of rocks and hills is just perfect.', '2007-07-10 16:41:37.000000', NULL, 1),
(3889777, 546680, 3087, '<td valign="top">Nice use of converging lines to create real depth - I like the way the main lines divide the image into four traingular segments. The contrast between the plain but worn concrete, the vibrant graffiti wall and the two green segments separated by sky is great. Very interesting. I can''t decide whether this would be even stronger with a small figure walking towards or away from us, positioned near that convergence point...?</td>', 'Nice use of converging lines to create real depth - I like the way the main lines divide the image into four traingular segments. The contrast between the plain but worn concrete, the vibrant graffiti wall and the two green segments separated by sky is great. Very interesting. I can''t decide whether this would be even stronger with a small figure walking towards or away from us, positioned near that convergence point...?', '2007-07-10 16:43:19.000000', NULL, 1),
(3889787, 547502, 3087, '<td valign="top">A peaceful image, with a slight air of loneliness, perhaps because of the wonderfully open landscape... I ike the three trees of varying sizes leading the eye into the emptiness. The compositoin, with foreground tree off to one side and the low horizon, works well. The sky full of cloud is not quite menacing but certainly a brooding presence. Nice toning.</td>', 'A peaceful image, with a slight air of loneliness, perhaps because of the wonderfully open landscape... I ike the three trees of varying sizes leading the eye into the emptiness. The compositoin, with foreground tree off to one side and the low horizon, works well. The sky full of cloud is not quite menacing but certainly a brooding presence. Nice toning.', '2007-07-10 16:45:12.000000', NULL, 1),
(3889807, 547974, 3087, '<td valign="top">This one doesn''t appeal to me hugely, I''m afraid. I don''t like the way that the information plaque is partially cropped out or that the plinth on which the monument sits touches the bottom edge of the frame - feels too tight. I''m also not keen on that huge dark swathe of roofing which takes up such a large chunk of the image and obscures the only bit that''s appealing to me - the mountains and natural landscape behind.</td>', 'This one doesn''t appeal to me hugely, I''m afraid. I don''t like the way that the information plaque is partially cropped out or that the plinth on which the monument sits touches the bottom edge of the frame - feels too tight. I''m also not keen on that huge dark swathe of roofing which takes up such a large chunk of the image and obscures the only bit that''s appealing to me - the mountains and natural landscape behind.', '2007-07-10 16:49:55.000000', NULL, 1),
(3889813, 548104, 3087, '<td valign="top">Frying pan not really interesting enough (or bold enough) to draw my attention or provide a focal point in amongst all that high contrast rock and dirt pattern. A little too nothingy a landscape to draw/ hold my interest.</td>', 'Frying pan not really interesting enough (or bold enough) to draw my attention or provide a focal point in amongst all that high contrast rock and dirt pattern. A little too nothingy a landscape to draw/ hold my interest.', '2007-07-10 16:51:20.000000', NULL, 1),
(3889819, 547769, 3087, '<td valign="top">A pretty corner and no doubt a lovely place to rest a moment. As a standalone image, this doesn''t appeal hugely. The scene, whilst pretty, isn''t one I find myself wanting to drink in or visit in person.</td>', 'A pretty corner and no doubt a lovely place to rest a moment. As a standalone image, this doesn''t appeal hugely. The scene, whilst pretty, isn''t one I find myself wanting to drink in or visit in person.', '2007-07-10 16:53:33.000000', NULL, 1),
(3889823, 547384, 3087, '<td valign="top">What a contrast between that arid earth and the rich blue of the sky! Unfortunately, for me, the lower half of the image is lacking a focal point or something to hold my interest - whether that''s a tree or person or building or just an unusual curve of hills. The placement of the horizon is also very centred making it even more static a composition.</td>', 'What a contrast between that arid earth and the rich blue of the sky! Unfortunately, for me, the lower half of the image is lacking a focal point or something to hold my interest - whether that''s a tree or person or building or just an unusual curve of hills. The placement of the horizon is also very centred making it even more static a composition.', '2007-07-10 16:54:47.000000', NULL, 1),
(3889929, 547848, 3087, '<td valign="top">Interesting light falling on the rocks but I''m not keen on the saturated orange of the sky, nor the strange pink and greens on the farthest rocks, especially since it''s those oddly coloured rocks that seem to be the main focal point, drawing my eye in.</td>', 'Interesting light falling on the rocks but I''m not keen on the saturated orange of the sky, nor the strange pink and greens on the farthest rocks, especially since it''s those oddly coloured rocks that seem to be the main focal point, drawing my eye in.', '2007-07-10 17:25:49.000000', NULL, 1),
(3889931, 547874, 3087, '<td valign="top">This doesn''t really work for me as an image. The composition feels messy - the foreground tree is tilted (which may be how it is in real life but when one can only see this small section of it, just makes the image feel unbalanced to me). The angle we have here makes the graveyard look cluttered and crowded rather than a peaceful resting place and the main cross we can see has it''s bottom cropped out. It seems that you can''t quite decide whether your subject is the foreground tree, the graves or the landscape beyond.</td>', 'This doesn''t really work for me as an image. The composition feels messy - the foreground tree is tilted (which may be how it is in real life but when one can only see this small section of it, just makes the image feel unbalanced to me). The angle we have here makes the graveyard look cluttered and crowded rather than a peaceful resting place and the main cross we can see has it''s bottom cropped out. It seems that you can''t quite decide whether your subject is the foreground tree, the graves or the landscape beyond.', '2007-07-10 17:26:06.000000', NULL, 1),
(3889947, 546272, 3087, '<td valign="top">My first reaction is that this feels very soft and I find myself squinting in an instinctive attempt to see more detail. I feel this is a scene that''s more striking in person than in this photograph. The scale isn''t easy to discern and there''s no real focal point - perhaps a foreground tree to give perspective AND compositional balance?</td>', 'My first reaction is that this feels very soft and I find myself squinting in an instinctive attempt to see more detail. I feel this is a scene that''s more striking in person than in this photograph. The scale isn''t easy to discern and there''s no real focal point - perhaps a foreground tree to give perspective AND compositional balance?', '2007-07-10 17:35:23.000000', NULL, 1),
(3889948, 547682, 3087, '<td valign="top">A pretty scene but not quite as strong an image - the foreground grass at the bottom left is too much in shadow for it to contribute anything more than just a sense of a dark smear. The lighting seems quite flat too - perhaps the early morning or late evening light would be more striking?</td>', 'A pretty scene but not quite as strong an image - the foreground grass at the bottom left is too much in shadow for it to contribute anything more than just a sense of a dark smear. The lighting seems quite flat too - perhaps the early morning or late evening light would be more striking?', '2007-07-10 17:35:32.000000', NULL, 1),
(3889990, 546271, 52713, '<td valign="top">I like the shot, but you''re probably getting a few DNMC due to the water.</td>', 'I like the shot, but you''re probably getting a few DNMC due to the water.', '2007-07-10 17:46:29.000000', NULL, 1),
(3889991, 547510, 52713, '<td valign="top">lovely colors and depth. 8</td>', 'lovely colors and depth. 8', '2007-07-10 17:46:56.000000', NULL, 1),
(3889993, 547809, 52713, '<td valign="top">nice BW conversion. 8</td>', 'nice BW conversion. 8', '2007-07-10 17:47:18.000000', NULL, 1),
(3889995, 547596, 52713, '<td valign="top">really pretty, A little heavy handed on the noise reduction. 7</td>', 'really pretty, A little heavy handed on the noise reduction. 7', '2007-07-10 17:47:48.000000', NULL, 1),
(3889998, 547602, 52713, '<td valign="top">good shadow detail and colors. 8</td>', 'good shadow detail and colors. 8', '2007-07-10 17:48:57.000000', NULL, 1),
(3890018, 547366, 3087, '<td valign="top">One of my top 7 images. I really like the texture and detail in that wonderful gnarled and weather-worn wood. The backdrop of similarly weather-worn rock works well, with the burnished copper colours of both. Deep blue sky and touches of green offset that orange well. And then there''s the perfectly posed little critter that just makes the perfect focal point and breaks up the orange too. Lovely.</td>', 'One of my top 7 images. I really like the texture and detail in that wonderful gnarled and weather-worn wood. The backdrop of similarly weather-worn rock works well, with the burnished copper colours of both. Deep blue sky and touches of green offset that orange well. And then there''s the perfectly posed little critter that just makes the perfect focal point and breaks up the orange too. Lovely.', '2007-07-10 17:54:12.000000', NULL, 1),
(3890019, 546391, 3087, '<td valign="top">One of my favourite 7 images. Great urban landscape. Love the framing and the different layers - foreground arch, nearest building, the road and pavement (sidewalk) with cars and people, buildings further back and then the cityscape fading into the mists of distance. Black and white fits perfectly and really brings out the geometry.</td>', 'One of my favourite 7 images. Great urban landscape. Love the framing and the different layers - foreground arch, nearest building, the road and pavement (sidewalk) with cars and people, buildings further back and then the cityscape fading into the mists of distance. Black and white fits perfectly and really brings out the geometry.', '2007-07-10 17:54:24.000000', NULL, 1),
(3890020, 547809, 3087, '<td valign="top">One of my favourite 7 in this challenge. A simple and common scene rendered striking by strong composition and really lovely high contrast black and white conversion.</td>', 'One of my favourite 7 in this challenge. A simple and common scene rendered striking by strong composition and really lovely high contrast black and white conversion.', '2007-07-10 17:55:00.000000', NULL, 1),
(3890027, 547571, 3087, '<td valign="top">One of my favourite 7 images. I really like the way that both foreground building interior and backdrop of beautiful historical city and hilly woodlands are of interest. It''s not often that the framing itself holds such interest and yet doesn''t compete with/ lessen the impact of the background. My only negative is the strong halos around the inner edges of the windows which presumably come from whichever technique you''ve used to balance exposure of foreground and background.</td>', 'One of my favourite 7 images. I really like the way that both foreground building interior and backdrop of beautiful historical city and hilly woodlands are of interest. It''s not often that the framing itself holds such interest and yet doesn''t compete with/ lessen the impact of the background. My only negative is the strong halos around the inner edges of the windows which presumably come from whichever technique you''ve used to balance exposure of foreground and background.', '2007-07-10 17:57:17.000000', NULL, 1),
(3890030, 548079, 3087, '<td valign="top">One of my favourite 7 images. Such a perfect capture of a scene so many of us see so very often. Really like the curved edge between where the windscreen wiper reaches and where it doesn''t. The low horizon/ expanse of cloudy sky works very well.</td>', 'One of my favourite 7 images. Such a perfect capture of a scene so many of us see so very often. Really like the curved edge between where the windscreen wiper reaches and where it doesn''t. The low horizon/ expanse of cloudy sky works very well.', '2007-07-10 17:58:35.000000', NULL, 1),
(3890040, 548010, 3087, '<td valign="top">One of my favourite 7 images. An intriguing portrait of a little corner that probably doesn''t get a second glance from most. The composition with the long leading lines to the door at the end works well. So too does the high contrast black and white conversion. But what I really love are the glimpses into the lives of those who live here, not by showing us the people, but by showing us a few of their personal items. Really fascinating.</td>', 'One of my favourite 7 images. An intriguing portrait of a little corner that probably doesn''t get a second glance from most. The composition with the long leading lines to the door at the end works well. So too does the high contrast black and white conversion. But what I really love are the glimpses into the lives of those who live here, not by showing us the people, but by showing us a few of their personal items. Really fascinating.', '2007-07-10 18:00:47.000000', NULL, 1),
(3890045, 545401, 3087, '<td valign="top">One of my favourite 7 images. Really like the vibrant colour, especially the lime green and bright blue, though these two colours only sing out because of the white and dark green/ black of the clouds and woods. Composition is just perfect with the low, low horizon and the huge expanse of sky, with the centred woods and the mainly low sitting clouds with just one lonely one at the top. Just wonderful.</td>', 'One of my favourite 7 images. Really like the vibrant colour, especially the lime green and bright blue, though these two colours only sing out because of the white and dark green/ black of the clouds and woods. Composition is just perfect with the low, low horizon and the huge expanse of sky, with the centred woods and the mainly low sitting clouds with just one lonely one at the top. Just wonderful.', '2007-07-10 18:02:28.000000', NULL, 1),
(3890060, 547863, 3087, '<td valign="top">What an unusual landscape image - almost abstract in it''s lack of sky, unusual viewpoint and minimal colours and yet immediately recognisable at the same time. Really make you focus on the limited subjects included - the lone life ring on it''s pole, the converging and criss-crossing footprints in the depression, the darker areas where the sand is presumably more water-logged...</td>', 'What an unusual landscape image - almost abstract in it''s lack of sky, unusual viewpoint and minimal colours and yet immediately recognisable at the same time. Really make you focus on the limited subjects included - the lone life ring on it''s pole, the converging and criss-crossing footprints in the depression, the darker areas where the sand is presumably more water-logged...', '2007-07-10 18:06:08.000000', NULL, 1),
(3890070, 547359, 3087, '<td valign="top">An image of two halves - I like how one half shows us the amazing stone-work of the ancient builders and the other shows us it''s environment - connected and yet separated by your composition. Only negatives for me, both minor, are the shadow at bottom right and also the image just seems rather strongly sharpened, though perhaps that''s just the strength of light and shadow?</td>', 'An image of two halves - I like how one half shows us the amazing stone-work of the ancient builders and the other shows us it''s environment - connected and yet separated by your composition. Only negatives for me, both minor, are the shadow at bottom right and also the image just seems rather strongly sharpened, though perhaps that''s just the strength of light and shadow?', '2007-07-10 18:07:58.000000', NULL, 1),
(3890075, 547596, 3087, '<td valign="top">Lovely image, like it a lot. Love the horizontal bands from top to bottom. Rather a strong halo all around the balloon which doesn''t look like natural backlighting, though perhaps it is?</td>', 'Lovely image, like it a lot. Love the horizontal bands from top to bottom. Rather a strong halo all around the balloon which doesn''t look like natural backlighting, though perhaps it is?', '2007-07-10 18:08:56.000000', NULL, 1),
(3890085, 547602, 3087, '<td valign="top">Lovely use of the dawn (or is it dusk) light and colours. Just enough detail in the foreground houses to show us what they are but not clutter with too much detail. Nice layers, foreground greenery, housing development, more greenery and then that jagged silhouette behind. Nice.</td>', 'Lovely use of the dawn (or is it dusk) light and colours. Just enough detail in the foreground houses to show us what they are but not clutter with too much detail. Nice layers, foreground greenery, housing development, more greenery and then that jagged silhouette behind. Nice.', '2007-07-10 18:10:30.000000', NULL, 1),
(3890090, 547843, 3087, '<td valign="top">Quintissential British countryside (though could equally be elsewhere in Europe). Lovely light, lovely sky detail, nice composition, inclusion of focal point house. Nice.</td>', 'Quintissential British countryside (though could equally be elsewhere in Europe). Lovely light, lovely sky detail, nice composition, inclusion of focal point house. Nice.', '2007-07-10 18:11:35.000000', NULL, 1),
(3890095, 547148, 3087, '<td valign="top">Beautiful combination of foreground and background - both of equal interest - the wheel with wonderful geometric shapes and colourful baskets and the city with it''s crowd of red buildings divided by wide roads. That slightly hazy sky makes a great backdrop for the top part of the shot too. All good!</td>', 'Beautiful combination of foreground and background - both of equal interest - the wheel with wonderful geometric shapes and colourful baskets and the city with it''s crowd of red buildings divided by wide roads. That slightly hazy sky makes a great backdrop for the top part of the shot too. All good!', '2007-07-10 18:13:02.000000', NULL, 1),
(3890100, 547913, 3087, '<td valign="top">Beautiful! Wonderful extreme saturation, cute foreground detail that really grounds the beautiful but fairly plain scene behind. Lovely lighting and exposure too.</td>', 'Beautiful! Wonderful extreme saturation, cute foreground detail that really grounds the beautiful but fairly plain scene behind. Lovely lighting and exposure too.', '2007-07-10 18:13:47.000000', NULL, 1),
(3890354, 547524, 76430, '<td valign="top">Sneaky!  OK, it''s not the sea, it''s San Francisco Bay.  Questionable about being a landscape though.  I do like the picture a lot, challenge theme notwithstanding.</td>', 'Sneaky!  OK, it''s not the sea, it''s San Francisco Bay.  Questionable about being a landscape though.  I do like the picture a lot, challenge theme notwithstanding.', '2007-07-10 19:09:34.000000', NULL, 1),
(3890396, 547432, 61818, '<td valign="top">I can only assume the tilt is some attempt to crop out a major distraction in the original shot?  Otherwise I can''t understand why in the world it was done.  I find it impossible to get past the angle, but the shot iself is well taken and a nice scene.</td>', 'I can only assume the tilt is some attempt to crop out a major distraction in the original shot?  Otherwise I can''t understand why in the world it was done.  I find it impossible to get past the angle, but the shot iself is well taken and a nice scene.', '2007-07-10 19:26:19.000000', NULL, 1),
(3890420, 547809, 70107, '<td valign="top">There is a farm field about 20 minutes from my house, and it looks just like this, and i was thinking that some day i should go and photograph it. And now that i see this i can only hope to be able to capture mine atleast half as good as what you have. I hope you win. This is definitly one of my favorites on the site.<br/>You get 100. :)</td>', 'There is a farm field about 20 minutes from my house, and it looks just like this, and i was thinking that some day i should go and photograph it. And now that i see this i can only hope to be able to capture mine atleast half as good as what you have. I hope you win. This is definitly one of my favorites on the site.You get 100. :)', '2007-07-10 19:33:08.000000', NULL, 1),
